helpers.stopOk:
(name, fn, kind, keys) => {
    let r = null, err = null;
    try { r = fn(); } catch (e) { err = e; }
    ok(name + " 例外なし", err == null, err ? String(err) : "");
    if (!r) return null;
    const c = r.checks.find((q) => q.level === "need" && q.kind === kind);
    ok(name + " need " + kind + " が出る", !!c, c ? c.title : "無し");
    if (keys) ok(name + " keys " + keys.join(","), !!c && keys.every((k) => ((c.data && c.data.keys) || []).includes(k)), c && c.data ? JSON.stringify(c.data.keys) : "");
    ok(name + " 片に NaN 無し", r.pieces.every((p) => [p.w, p.h, p.kg].every((x) => !Number.isNaN(x))), r.pieces.map((p) => `${p.label} ${p.w}/${p.h}/${p.kg}`).join("・"));
    return r;
  }

